/* ---------- palette ---------- */
const C = {
  page: "#12161f",
  panel: "#1b212e",
  ocean: "#0c1219",
  land: "#39445a",
  amber: "#e3a542",
  cream: "#f3e9d8",
  green: "#5fbf7a",
  red: "#e2645a",
  border: "#7c88a3",
  muted: "#8b94a8",
  line: "#2b3242",
};

/* ---------- projection: Mercator, hand rolled ---------- */
const VB_W = 760;
const PAD = 24;
const D2R = Math.PI / 180;

function merc(lon, lat) {
  const la = Math.max(-85, Math.min(85, lat));
  return [lon * D2R, Math.log(Math.tan(Math.PI / 4 + (la * D2R) / 2))];
}
function unmerc(x, y) {
  return [x / D2R, (2 * Math.atan(Math.exp(y)) - Math.PI / 2) / D2R];
}

const FIT = (() => {
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const c of RAW)
    for (const poly of c.p)
      for (const ring of poly)
        for (let i = 0; i < ring.length; i += 2) {
          const [x, y] = merc(ring[i], ring[i + 1]);
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
  const s = (VB_W - 2 * PAD) / (x1 - x0);
  return { x0, y1, s, h: Math.round((y1 - y0) * s + 2 * PAD) };
})();
const VB_H = FIT.h;

function project(lon, lat) {
  const [x, y] = merc(lon, lat);
  return [(x - FIT.x0) * FIT.s + PAD, (FIT.y1 - y) * FIT.s + PAD];
}
function invert(px, py) {
  return unmerc((px - PAD) / FIT.s + FIT.x0, FIT.y1 - (py - PAD) / FIT.s);
}

/* ---------- point in polygon: even-odd across every ring ---------- */
function ringHit(ring, lon, lat) {
  let inside = false;
  const n = ring.length / 2;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = ring[i * 2], yi = ring[i * 2 + 1];
    const xj = ring[j * 2], yj = ring[j * 2 + 1];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi)
      inside = !inside;
  }
  return inside;
}
function containsLonLat(polys, lon, lat) {
  for (const poly of polys) {
    let inside = false;
    for (const ring of poly) if (ringHit(ring, lon, lat)) inside = !inside;
    if (inside) return true;
  }
  return false;
}

/* ---------- derived county model ---------- */
const SMALL_PIECE_MAX = 30; // projected units
const TAP_TOL = 28; // projected units at zoom 1; see notes

const COUNTIES = RAW.map((c, id) => {
  const pieces = c.p.map((poly) => {
    let d = "";
    let minx = Infinity, maxx = -Infinity, miny = Infinity, maxy = -Infinity;
    const proj = [];
    for (const ring of poly) {
      const pr = [];
      for (let i = 0; i < ring.length; i += 2) {
        const p = project(ring[i], ring[i + 1]);
        pr.push(p);
        d += (i === 0 ? "M" : "L") + p[0].toFixed(2) + " " + p[1].toFixed(2);
      }
      d += "Z";
      proj.push(pr);
      for (const p of pr) {
        if (p[0] < minx) minx = p[0];
        if (p[0] > maxx) maxx = p[0];
        if (p[1] < miny) miny = p[1];
        if (p[1] > maxy) maxy = p[1];
      }
    }
    return {
      d,
      proj,
      span: Math.max(maxx - minx, maxy - miny),
      cx: (minx + maxx) / 2,
      cy: (miny + maxy) / 2,
    };
  });
  const all = pieces.flatMap((p) => p.proj.flat());
  const bx = [Math.min(...all.map((p) => p[0])), Math.max(...all.map((p) => p[0]))];
  const by = [Math.min(...all.map((p) => p[1])), Math.max(...all.map((p) => p[1]))];
  const marker = project(c.m[0], c.m[1]);
  const smallPieces = pieces.filter((p) => p.span < SMALL_PIECE_MAX);
  return {
    id,
    name: c.n,
    answers: c.a,
    polys: c.p,
    pieces,
    d: pieces.map((p) => p.d).join(""),
    marker,
    span: Math.max(bx[1] - bx[0], by[1] - by[0]),
    smallPieces,
    // outlying pieces get a leader line back to the mainland marker
    outliers: smallPieces.filter((p) => Math.hypot(p.cx - marker[0], p.cy - marker[1]) > 40),
  };
});

const TINY = COUNTIES.filter((c) => c.span < SMALL_PIECE_MAX); // whole county is a speck
const TOL_TARGETS = COUNTIES.filter((c) => c.smallPieces.length > 0);

const BORDER_PATH = COUNTIES.map((c) => c.d).join("");

/* ---------- answer normalisation ---------- */
function normalise(s) {
  return s
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z]+/g, " ")
    .trim()
    .replace(/\s+county$/, "")
    .trim();
}
function matches(county, raw) {
  const n = normalise(raw);
  return n.length > 0 && county.answers.indexOf(n) !== -1;
}

/* ---------- tap resolution ---------- */
function nearestVertexDist(pieces, x, y) {
  let best = Infinity;
  for (const piece of pieces)
    for (const ring of piece.proj)
      for (const p of ring) {
        const d = Math.hypot(p[0] - x, p[1] - y);
        if (d < best) best = d;
      }
  return best;
}

/**
 * Resolve a tap at projected point (x,y).
 * 1. inside target -> hit
 * 2. inside any other county -> that county
 * 3. open water within TAP_TOL/zoom of a small unit's coastline -> that unit
 * 4. otherwise null (open water)
 */
function resolveTap(x, y, targetId, zoom) {
  const [lon, lat] = invert(x, y);
  const target = COUNTIES[targetId];
  if (target && containsLonLat(target.polys, lon, lat)) return target;
  for (const c of COUNTIES)
    if (c.id !== targetId && containsLonLat(c.polys, lon, lat)) return c;

  const tol = TAP_TOL / zoom;
  const pool = target && TOL_TARGETS.indexOf(target) !== -1
    ? [target, ...TOL_TARGETS.filter((c) => c !== target)]
    : TOL_TARGETS;
  let best = null, bestD = tol;
  for (const c of pool) {
    const d = nearestVertexDist(c.smallPieces, x, y);
    if (d < bestD) { bestD = d; best = c; }
    if (c === target && d < tol) return c; // target wins ties
  }
  return best;
}

/* ---------- gestures ---------- */
const MIN_Z = 1, MAX_Z = 12;

function useMapGestures(onTapRaw) {
  const svgRef = useRef(null);
  const [view, setView] = useState({ z: 1, tx: 0, ty: 0 });
  const tapRef = useRef(onTapRaw);
  tapRef.current = onTapRaw;
  const onTap = useCallback((x, y, z) => tapRef.current && tapRef.current(x, y, z), []);
  const g = useRef({ mode: null, sx: 0, sy: 0, moved: false, dist: 0, lastTouch: 0 });

  const toVB = useCallback((cx, cy) => {
    const el = svgRef.current;
    if (!el) return [0, 0];
    const r = el.getBoundingClientRect();
    return [((cx - r.left) / r.width) * VB_W, ((cy - r.top) / r.height) * VB_H];
  }, []);

  const zoomAbout = useCallback((vx, vy, factor) => {
    setView((v) => {
      const z = Math.max(MIN_Z, Math.min(MAX_Z, v.z * factor));
      const k = z / v.z;
      return { z, tx: vx - k * (vx - v.tx), ty: vy - k * (vy - v.ty) };
    });
  }, []);

  const toMap = useCallback((vx, vy) => {
    const v = view;
    return [(vx - v.tx) / v.z, (vy - v.ty) / v.z];
  }, [view]);

  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;

    const onTouchStart = (e) => {
      if (e.touches.length >= 2) {
        e.preventDefault();
        const [a, b] = [e.touches[0], e.touches[1]];
        g.current.mode = "pinch";
        g.current.dist = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
      } else if (e.touches.length === 1) {
        g.current.mode = "maybe-tap";
        g.current.sx = e.touches[0].clientX;
        g.current.sy = e.touches[0].clientY;
        g.current.moved = false;
      }
    };

    const onTouchMove = (e) => {
      if (e.touches.length >= 2) {
        e.preventDefault();
        const [a, b] = [e.touches[0], e.touches[1]];
        const d = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
        if (g.current.mode !== "pinch") { g.current.mode = "pinch"; g.current.dist = d; return; }
        const mid = toVB((a.clientX + b.clientX) / 2, (a.clientY + b.clientY) / 2);
        if (g.current.dist > 0) zoomAbout(mid[0], mid[1], d / g.current.dist);
        g.current.dist = d;
      } else if (g.current.mode === "maybe-tap" && e.touches.length === 1) {
        const dx = e.touches[0].clientX - g.current.sx;
        const dy = e.touches[0].clientY - g.current.sy;
        if (Math.hypot(dx, dy) > 10) g.current.moved = true;
      }
    };

    const endTouch = (e) => {
      if (g.current.mode === "maybe-tap" && !g.current.moved) {
        g.current.lastTouch = Date.now();
        const vb = toVB(g.current.sx, g.current.sy);
        const m = toMap(vb[0], vb[1]);
        onTap(m[0], m[1], view.z);
      }
      if (e.touches.length === 0) g.current.mode = null;
    };

    const onWheel = (e) => {
      e.preventDefault();
      const vb = toVB(e.clientX, e.clientY);
      zoomAbout(vb[0], vb[1], e.deltaY < 0 ? 1.15 : 1 / 1.15);
    };

    el.addEventListener("touchstart", onTouchStart, { passive: false });
    el.addEventListener("touchmove", onTouchMove, { passive: false });
    el.addEventListener("touchend", endTouch, { passive: false });
    el.addEventListener("touchcancel", endTouch, { passive: false });
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("touchstart", onTouchStart);
      el.removeEventListener("touchmove", onTouchMove);
      el.removeEventListener("touchend", endTouch);
      el.removeEventListener("touchcancel", endTouch);
      el.removeEventListener("wheel", onWheel);
    };
  }, [toVB, toMap, zoomAbout, onTap, view.z]);

  const onClick = (e) => {
    // mobile browsers fire a synthetic click after touch; suppress it
    if (Date.now() - g.current.lastTouch < 600) return;
    const vb = toVB(e.clientX, e.clientY);
    const m = toMap(vb[0], vb[1]);
    onTap(m[0], m[1], view.z);
  };

  const reset = () => setView({ z: 1, tx: 0, ty: 0 });
  return { svgRef, view, onClick, reset };
}

/* ---------- map ---------- */
function MapView({ target, solved, revealed, wrong, borders, mode, onTapPoint, label }) {
  const g = useMapGestures(onTapPoint);
  const { view } = g;
  const sw = 1 / view.z;

  const fillFor = (c) => {
    if (wrong && c.id === wrong.id) return C.red;
    if (revealed && c.id === revealed.id) return C.green;
    if (solved && solved.has(c.id)) return C.amber;
    if (mode === "type" && target && c.id === target.id) return C.cream;
    return C.land;
  };

  const highlighted = revealed || (mode === "type" ? target : null);

  return (
    <div className="ad-mapwrap">
      <svg
        ref={g.svgRef}
        className="ad-map"
        viewBox={`0 0 ${VB_W} ${VB_H}`}
        preserveAspectRatio="xMidYMid meet"
        role="img"
        aria-label={label}
        onClick={g.onClick}
      >
        <rect x="0" y="0" width={VB_W} height={VB_H} fill={C.ocean} />
        <g transform={`translate(${view.tx} ${view.ty}) scale(${view.z})`}>
          {COUNTIES.map((c) => {
            const f = fillFor(c);
            return (
              <path
                key={c.id}
                d={c.d}
                fill={f}
                stroke={f}
                strokeWidth={sw}
                fillRule="evenodd"
              />
            );
          })}

          {/* locator ring for counties too small to see at 1x */}
          {TINY.map((c) => {
            const on = highlighted && c.id === highlighted.id;
            const gold = solved && solved.has(c.id) && !on;
            if (!on && !gold) return null;
            return (
              <circle
                key={"r" + c.id}
                cx={c.marker[0]}
                cy={c.marker[1]}
                r={(on ? 22 : 14) / Math.max(1, view.z * 0.6)}
                fill="none"
                stroke={on ? (revealed ? C.green : mode === "type" ? C.cream : C.amber) : C.amber}
                strokeWidth={1.6 / view.z}
                opacity="0.85"
              />
            );
          })}

          {/* leader lines from offshore islands back to the mainland */}
          {highlighted &&
            highlighted.outliers.map((p, i) => (
              <g key={"o" + i}>
                <line
                  x1={p.cx}
                  y1={p.cy}
                  x2={highlighted.marker[0]}
                  y2={highlighted.marker[1]}
                  stroke={revealed ? C.green : mode === "type" ? C.cream : C.amber}
                  strokeWidth={0.8 / view.z}
                  strokeDasharray={`${3 / view.z} ${3 / view.z}`}
                  opacity="0.6"
                />
                <circle
                  cx={p.cx}
                  cy={p.cy}
                  r={12 / Math.max(1, view.z * 0.6)}
                  fill="none"
                  stroke={revealed ? C.green : mode === "type" ? C.cream : C.amber}
                  strokeWidth={1.2 / view.z}
                  opacity="0.7"
                />
              </g>
            ))}

          {/* border overlay: one path, drawn above every fill */}
          {borders && (
            <path
              d={BORDER_PATH}
              fill="none"
              stroke={C.border}
              strokeWidth={0.9 / view.z}
              strokeLinejoin="round"
              opacity="0.85"
            />
          )}
        </g>
      </svg>
      {view.z > 1.01 && (
        <button className="ad-reset" onClick={g.reset}>
          Reset view
        </button>
      )}
    </div>
  );
}

/* ---------- climb ---------- */
const SUMMIT_M = 4421; // Mount Whitney
const WAYPOINTS = [
  ["Whitney Portal", 0],
  ["Lone Pine Lake", 0.2],
  ["Outpost Camp", 0.4],
  ["Trail Camp", 0.6],
  ["Trail Crest", 0.82],
  ["Whitney Summit", 1],
];

function Altimeter({ solved, total }) {
  const frac = solved / total;
  const metres = Math.round(frac * SUMMIT_M);
  const reached = WAYPOINTS.filter((w) => frac >= w[1]);
  const here = reached[reached.length - 1];
  return (
    <div className="ad-climb">
      <div className="ad-climb-head">
        <span className="ad-wp">{here[0]}</span>
        <span className="ad-alt">
          {metres.toLocaleString()} m<span className="ad-of"> / 4,421</span>
        </span>
      </div>
      <div className="ad-track">
        <div className="ad-fill" style={{ width: `${frac * 100}%` }} />
        {WAYPOINTS.map((w) => (
          <div
            key={w[0]}
            className={"ad-tick" + (frac >= w[1] ? " on" : "")}
            style={{ left: `${w[1] * 100}%` }}
            title={w[0]}
          />
        ))}
      </div>
      <div className="ad-climb-sub">
        {solved} of {total} counties
      </div>
    </div>
  );
}

/* ---------- quiz ---------- */
function shuffle(a) {
  const r = a.slice();
  for (let i = r.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [r[i], r[j]] = [r[j], r[i]];
  }
  return r;
}
const ALL_IDS = COUNTIES.map((c) => c.id);

function Quiz({ input, session, borders, climb, setClimb }) {
  const isClimb = session === "climb";

  const [queue, setQueue] = useState(() => shuffle(ALL_IDS));
  const [score, setScore] = useState({ right: 0, total: 0 });
  // the previous answer, kept only so its highlight lingers into the next
  // question. There is no waiting phase: every answer advances immediately.
  const [last, setLast] = useState(null); // { id, ok, pickedId, water }
  const [text, setText] = useState("");
  const inputRef = useRef(null);

  // climb state lives one level up so it survives an input-mode switch
  const solved = climb.solved;

  const activeQueue = isClimb ? climb.queue : queue;
  const targetId = activeQueue.length ? activeQueue[0] : null;
  const target = targetId === null ? null : COUNTIES[targetId];

  useEffect(() => {
    if (!isClimb) { setQueue(shuffle(ALL_IDS)); setScore({ right: 0, total: 0 }); }
    setLast(null);
    setText("");
  }, [session, isClimb]);

  const answer = (ok, picked) => {
    if (target === null) return;
    if (isClimb) {
      setClimb((s) => {
        const next = new Set(s.solved);
        if (ok) next.add(target.id); // idempotent: re-adding is a no-op
        return {
          solved: next,
          guesses: s.guesses + 1,
          // correct: leave the queue for good, and let it empty on the last
          // one rather than reshuffling. Miss: rotate to the back, cost nothing.
          queue: ok ? s.queue.slice(1) : [...s.queue.slice(1), s.queue[0]],
        };
      });
    } else {
      setScore((s) => ({ right: s.right + (ok ? 1 : 0), total: s.total + 1 }));
      setQueue((q) => (q.length <= 1 ? shuffle(ALL_IDS) : q.slice(1)));
    }
    setLast({
      id: target.id,
      ok,
      pickedId: picked ? picked.id : null,
      water: input === "tap" && !ok && !picked,
    });
    setText("");
    if (input === "type") setTimeout(() => inputRef.current && inputRef.current.focus(), 0);
  };

  const submitText = () => {
    if (!text.trim() || !target) return;
    answer(matches(target, text), null);
  };

  const handleTap = useCallback(
    (x, y, z) => {
      if (!target) return;
      const hit = resolveTap(x, y, target.id, z || 1);
      answer(!!hit && hit.id === target.id, hit);
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [target, isClimb, input]
  );

  const summited = isClimb && climb.queue.length === 0;

  if (summited) {
    return (
      <div className="ad-summit">
        <div className="ad-summit-alt">4,421 m</div>
        <h2>Whitney Summit</h2>
        <p>All 58 counties. {climb.guesses} guesses to the top.</p>
        <button
          className="ad-btn primary"
          onClick={() => { setLast(null); setClimb({ solved: new Set(), queue: shuffle(ALL_IDS), guesses: 0 }); }}
        >
          Climb again
        </button>
      </div>
    );
  }

  // lingering highlights from the previous answer. Suppressed if the county
  // in question is the one being asked about now, which would give it away.
  const lingerId = last && last.id !== targetId ? last.id : null;
  const revealed = lingerId === null ? null : COUNTIES[lingerId];
  const missed =
    last && last.pickedId !== null && last.pickedId !== last.id && last.pickedId !== targetId
      ? COUNTIES[last.pickedId]
      : null;

  const pct = score.total ? Math.round((score.right / score.total) * 100) : 0;

  return (
    <>
      {isClimb ? (
        <Altimeter solved={solved.size} total={COUNTIES.length} />
      ) : (
        <div className="ad-score">
          <span className="ad-mono">
            {score.right}/{score.total}
          </span>
          <span className="ad-pct">{score.total ? pct + "%" : "\u2014"}</span>
        </div>
      )}

      <div className="ad-prompt">
        {input === "tap" ? (
          <>
            <span className="ad-eyebrow">Find</span>
            <span className="ad-name">{target ? target.name : ""}</span>
          </>
        ) : (
          <span className="ad-eyebrow">Name the highlighted county</span>
        )}
      </div>

      <MapView
        target={target}
        solved={isClimb ? solved : null}
        revealed={revealed}
        wrong={missed}
        borders={borders}
        mode={input}
        onTapPoint={input === "tap" ? handleTap : null}
        label={
          input === "tap"
            ? `Map of California. Tap ${target ? target.name : ""} County.`
            : `Map of California with one county highlighted. Type its name.`
        }
      />

      <div className="ad-answer">
        {input === "type" ? (
          <div className="ad-row">
            <input
              ref={inputRef}
              className="ad-input"
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") submitText(); }}
              placeholder="County name"
              autoCapitalize="words"
              autoCorrect="off"
              autoComplete="off"
              spellCheck="false"
              aria-label="County name"
            />
            <button className="ad-btn primary" onClick={submitText}>
              Check
            </button>
          </div>
        ) : null}

        <div className="ad-feedback" aria-live="polite">
          {last && last.ok && (
            <span className="ok">
              Correct — <b>{COUNTIES[last.id].name}</b>
            </span>
          )}
          {last && !last.ok && (
            <span className="miss">
              {missed ? `${missed.name}, not ` : last.water ? "Open water, not " : "Missed "}
              <b>{COUNTIES[last.id].name}</b>
              {lingerId !== null ? ", still on the map in green." : "."}
            </span>
          )}
        </div>
      </div>
    </>
  );
}

/* ---------- shell ---------- */
export default function AtlasDrillCalifornia() {
  const [input, setInput] = useState("type"); // type | tap
  const [session, setSession] = useState("practice"); // practice | climb
  // County lines on by default: the outline is the thing you're naming, and
  // in tap mode it's what you're aiming at.
  const [borders, setBorders] = useState(true);
  const [climb, setClimb] = useState(() => ({
    solved: new Set(),
    queue: shuffle(ALL_IDS),
    guesses: 0,
  }));

  const startClimb = () => setClimb({ solved: new Set(), queue: shuffle(ALL_IDS), guesses: 0 });

  return (
    <div className="ad-page">
      <style>{CSS}</style>
      <div className="ad-panel">
        <header className="ad-head">
          <h1>Atlas Drill</h1>
          <p className="ad-sub">The 58 counties of California</p>
        </header>

        <div className="ad-controls">
          <div className="ad-seg" role="group" aria-label="Answer mode">
            <button
              className={input === "type" ? "on" : ""}
              onClick={() => setInput("type")}
              aria-pressed={input === "type"}
            >
              Name it
            </button>
            <button
              className={input === "tap" ? "on" : ""}
              onClick={() => setInput("tap")}
              aria-pressed={input === "tap"}
            >
              Find it
            </button>
          </div>
          <div className="ad-seg" role="group" aria-label="Session mode">
            <button
              className={session === "practice" ? "on" : ""}
              onClick={() => setSession("practice")}
              aria-pressed={session === "practice"}
            >
              Practice
            </button>
            <button
              className={session === "climb" ? "on" : ""}
              onClick={() => { if (session !== "climb") { startClimb(); setSession("climb"); } }}
              aria-pressed={session === "climb"}
            >
              Whitney
            </button>
          </div>
          <button
            className={"ad-toggle" + (borders ? " on" : "")}
            onClick={() => setBorders((b) => !b)}
            aria-pressed={borders}
          >
            Borders
          </button>
        </div>

        <Quiz
          key={session}
          input={input}
          session={session}
          borders={borders}
          climb={climb}
          setClimb={setClimb}
        />

        <footer className="ad-foot">
          Pinch or scroll to zoom. Borders are hidden on purpose — read the coastline
          and the shape of the valley.
        </footer>
      </div>
    </div>
  );
}

